export type CartState = { cartId: string; selectedCoupon: null | { couponCode: string } };

export function applySelectedCoupon(cartState: CartState) {
  // BUG: selectedCoupon can be null when the user has not picked a coupon.
  // Expected guard: if (!cartState.selectedCoupon) return null;
  return cartState.selectedCoupon.couponCode.toUpperCase();
}
